// Regenerates src/features/legal/content.generated.ts from the legal drafts (docs/legal/drafts/*.md), without the
// drafting notes for counsel. Run after editing a draft:  node scripts/legal-content.mjs
// src/features/legal/content.test.ts fails while the generated file is out of step with the drafts.
import { readFileSync, writeFileSync } from 'node:fs'
import { LEGAL_DRAFT_FILES, stripDraftingNotes } from '../src/features/legal/source.ts'

const root = new URL('..', import.meta.url)
const read = (path) => stripDraftingNotes(readFileSync(new URL(path, root), 'utf8'))
const lines = [
  '// GENERATED by scripts/legal-content.mjs from docs/legal/drafts/*.md. Do not edit; edit the drafts and re-run the script.',
  '// Drafting notes for counsel are removed (source.ts); the drafts README lists them.',
  '',
  'export const LEGAL_CONTENT = {',
]
for (const [doc, langs] of Object.entries(LEGAL_DRAFT_FILES)) {
  lines.push(`  ${doc}: {`)
  for (const [lang, path] of Object.entries(langs)) lines.push(`    ${lang}: ${JSON.stringify(read(path))},`)
  lines.push('  },')
}
lines.push('} as const', '')
writeFileSync(new URL('src/features/legal/content.generated.ts', root), lines.join('\n'))
console.log('wrote src/features/legal/content.generated.ts')
